/* eslint-disable react/require-default-props */
import React, { HTMLProps } from 'react';
import { styled, config } from '@hexa-ui/theme';
import { Slot } from '@radix-ui/react-slot';
import type * as Stitches from '@stitches/react';
import { TextLinkCSS } from './TextLink.styles';

type CSSVariants = Stitches.CSS<typeof config>;

type ConditionalProps =
  | {
      asChild?: boolean;
      children: React.ReactNode;
    }
  | (Omit<HTMLProps<HTMLAnchorElement>, 'size'> & {
      asChild?: never;
    });

type BaseProps = {
  size?: 'basis' | 'small' | 'xsmall';
  colorOption?: 'blue' | 'black';
  hasUnderline?: boolean;
  alignment?: 'left' | 'center' | 'right';
  css?: CSSVariants;
};

export type TextLinkTypes = ConditionalProps & BaseProps;

const StyledSlot = styled(Slot, TextLinkCSS);
const StyledAnchor = styled('a', TextLinkCSS);

export const TextLink = React.forwardRef(
  (
    {
      colorOption = 'blue',
      hasUnderline = true,
      size = 'basis',
      alignment = 'left',
      asChild = false,
      css,
      ...props
    }: TextLinkTypes,
    forwardedRef: React.ForwardedRef<HTMLAnchorElement>
  ): JSX.Element => {
    const Comp = asChild ? StyledSlot : StyledAnchor;
    return (
      <Comp
        colorOption={colorOption}
        hasUnderline={hasUnderline}
        size={size}
        alignment={alignment}
        css={css}
        {...props}
        ref={forwardedRef}
      />
    );
  }
);
